-- PROMOCION CONTROLADA V4 -> V5 | 2026-11-21
-- DESTINO EXCLUSIVO: mayalexhn-prod | Supabase project ref thgrhueckkjdutjvcufp
-- ESTE SQL NO PUEDE DETECTAR EL PROJECT REF DE LA CONEXION. Antes de ejecutar, confirme visualmente el ref en el SQL Editor.
-- Ejecutar solo en el proyecto anterior. No usar credenciales de staging ni de otro proyecto.
-- Crea snapshot de las filas actuales de estos tres instrumentos (no sustituye PITR/backup integral ni una prueba de restauración).
-- Si el nombre de respaldo ya existe, detenerse y revisar; no borrarlo ni reutilizarlo a ciegas.
BEGIN;
CREATE TABLE public.biblioteca_vectores_v5_20261121_backup AS
SELECT b.*
FROM public.biblioteca_vectores AS b
WHERE b.instrumento_id IN ('CODIGO_NINEZ','DECRETO_35_2013','DECRETO_284_2013')
   OR b.metadata->>'norm_id' IN ('HN:CODIGO_NINEZ','HN:DECRETO_35_2013','HN:DECRETO_284_2013')
   OR b.ingest_batch IN ('A03_CODIGO_NINEZ_01','A04_D35_2013_01','PILOTO_D284_2013_01');
COMMIT;

-- Estado actual por instrumento, antes de cualquier INSERT/UPDATE.
SELECT e.norm_id, e.instrumento_id,
       count(b.id) AS filas_existentes,
       count(b.id) FILTER (WHERE b.metadata->>'estado_v' = 'V4') AS filas_v4,
       count(b.id) FILTER (WHERE b.metadata->>'estado_v' = 'V5') AS filas_v5,
       count(b.id) FILTER (WHERE b.revision_pendiente = false) AS visibles,
       count(b.id) FILTER (WHERE b.embedding IS NOT NULL) AS con_embedding,
       count(b.id) FILTER (WHERE b.hash_contenido IS NOT NULL AND encode(sha256(convert_to(b.contenido, 'UTF8')), 'hex') = b.hash_contenido) AS sha_ok
FROM (VALUES
  ('HN:CODIGO_NINEZ','CODIGO_NINEZ'),
  ('HN:DECRETO_35_2013','DECRETO_35_2013'),
  ('HN:DECRETO_284_2013','DECRETO_284_2013')
) AS e(norm_id, instrumento_id)
LEFT JOIN public.biblioteca_vectores AS b
  ON b.instrumento_id = e.instrumento_id OR b.metadata->>'norm_id' = e.norm_id
GROUP BY e.norm_id, e.instrumento_id
ORDER BY e.norm_id;


